function h(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function uid(prefix){return (prefix||'SE')+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase();}
function companyId(){try{return typeof ccid==='function'?(ccid()||prof?.company_id||co?.id):prof?.company_id||co?.id||null;}catch(_){return null;}}
function personName(){return prof?.full_name||prof?.name||prof?.email||'Current user';}
function personId(){return prof?.id||null;}
function role(){try{return typeof activeRole==='function'?activeRole():(prof?.role||'employee');}catch(_){return 'employee';}}
