function actionButton(label,fn,kind,icon){return '<button class="se-btn '+(kind||'')+'" data-auris-module-onclick="f0062" data-auris-module-command="'+encodeURIComponent(fn)+'">'+(icon?'<i class="ti '+icon+'"></i>':'')+h(label)+'</button>';}
function metric(icon,label,value,note,tone,onclick){return '<div class="se-card se-metric '+(tone?'se-tone-'+tone:'')+(onclick?' se-clickable':'')+'" '+(onclick?'role="button" tabindex="0" data-auris-module-onclick="f0062" data-auris-module-command="'+encodeURIComponent(onclick)+'"':'')+'><div class="se-metric-icon"><i class="ti '+icon+'"></i></div><div class="se-metric-label">'+h(label)+'</div><div class="se-metric-value">'+h(value)+'</div><div class="se-metric-note">'+h(note||'')+'</div></div>';}
function empty(title,text,action){return '<div class="se-empty"><i class="ti ti-inbox"></i><strong>'+h(title)+'</strong><span>'+h(text)+'</span>'+(action||'')+'</div>';}
