  if(!rs.length)return permittedEmpty('No engagement results for '+currentPeriodLabel(),'Cards and charts appear after assignments produce traceable activity and calculated results.',canManage()?'Create programme':null,"seOpenDrawer('programme')");
  var scored=rs.filter(function(x){return x.score!==null&&x.score!==undefined;}),avg=scored.length?Math.round(scored.reduce(function(a,x){return a+(+x.score||0);},0)/scored.length):null,exclusions=rs.reduce(function(a,x){return a+(+x.excluded||0);},0),activities={};
  rs.forEach(function(r){((r.calculation&&r.calculation.kpis)||[]).forEach(function(k){var key=k.name||k.code||'KPI',value=Number(k.achievement);if(Number.isFinite(value)){activities[key]=activities[key]||[];activities[key].push(value);}});});
