  if(step===2){var pending=rs.reduce(function(a,x){return a+(+x.pending||0);},0),missing=rs.filter(function(x){return x.score==null;}).length,disputes=(SE.data.disputes||[]).filter(function(x){return !['closed','approved'].includes(x.status);}).length;return '<div class="se-readiness">'+[['Eligible employees',rs.length,'Included by current assignment/supervisory scope'],['Pending validations',pending,'Review may be saved; submission follows configured policy'],['Missing results',missing,'Resolve source error, Not Due or justified N/A'],['Open disputes',disputes,'Affected locked results cannot be finalised']].map(function(x){return '<button data-auris-module-onclick="f0002" data-auris-module-args="'+encodeURIComponent(JSON.stringify([(x[0]==='Pending validations'?'validation':x[0]==='Open disputes'?'disputes':'monthly')]))+'"><strong>'+h(x[1])+'</strong><span>'+h(x[0])+'</span><small>'+h(x[2])+'</small></button>';}).join('')+'</div><div class="se-note">Last calculation refresh: '+h(new Date().toLocaleString())+'</div>';}
  if(step===3)return '<div class="se-review-employees">'+rs.map(function(x){var assessment=(review.assessments||{})[x.id]||{};return '<details><summary><span><b>'+h(x.person_name)+'</b><small>'+h(x.programme_name)+'</small></span>'+badge(x.status)+'</summary><div class="se-review-grid"><div class="se-record-summary"><div class="se-detail-row"><span>System score</span><b>'+(x.score==null?'No Data':h(x.score)+'%')+'</b></div><div class="se-detail-row"><span>Pending</span><b>'+h(x.pending||0)+'</b></div><div class="se-detail-row"><span>Exclusions</span><b>'+h(x.excluded||0)+'</b></div></div>'+field('Supervisor assessment','se-tr-assess-'+x.id,'select',[['confirmed','Confirmed'],['needs_correction','Needs Correction'],['recognition','Recognition Recommended'],['coaching','Coaching Recommended'],['no_action','Reviewed — No Additional Action']],assessment.decision||'confirmed')+field('Review comment','se-tr-comment-'+x.id,'textarea',null,assessment.comment||'',true)+'</div></details>';}).join('')+'</div>';
  if(step===4)return '<div class="se-form-grid">'+field('Achievements','se-tr-achievements','textarea',null,review.achievements||'',true)+field('Key barriers','se-tr-barriers','textarea',null,review.barriers||'',true)+field('Recurring themes','se-tr-themes','textarea',null,review.themes||'',true)+field('Team actions','se-tr-actions','textarea',null,review.actions_text||'',true)+field('Escalations','se-tr-escalations','textarea',null,review.escalations||'',true)+field('Overall conclusion','se-tr-conclusion','select',[['on_track','On Track'],['attention_required','Attention Required'],['management_support','Management Support Required']],review.conclusion||'on_track')+'</div><label class="se-check"><input id="se-tr-declaration" type="checkbox" '+(review.declaration?'checked':'')+'> I confirm that results were reviewed fairly and incident reporting was not discouraged.</label>';
  var assessments=review.assessments||{},reviewed=Object.keys(assessments).length;return '<div class="se-grid two"><div class="se-card"><div class="se-card-title">Completeness</div><div class="se-detail-row"><span>Employees reviewed</span><b>'+reviewed+' / '+rs.length+'</b></div><div class="se-detail-row"><span>Pending validations</span><b>'+rs.reduce(function(a,x){return a+(+x.pending||0);},0)+'</b></div><div class="se-detail-row"><span>Declaration</span><b>'+(review.declaration?'Confirmed':'Required')+'</b></div></div><div class="se-card"><div class="se-card-title">Submission impact</div><p>Creates a versioned snapshot of employee results and linked source references. Draft recognition, coaching, correction and action records are created idempotently from the review.</p>'+badge(review.status||'draft')+'</div></div>';
