window.seOpenTeamReview=function(id){var active=id?findBy('teamReviews',id):(SE.data.teamReviews||[]).find(function(x){return x.period===SE.period&&['draft','returned'].includes(x.status);});var templates=(SE.data.reviewTemplates||[]).filter(function(x){return x.status==='published'&&(!x.effective_from||x.effective_from<=SE.period+'-28');});if(!active&&!(SE.data.results||[]).some(function(x){return x.period===SE.period;}))return drawer('Start Team Review',empty('No eligible team members','A review cannot be created without eligible assigned employees.'));if(!active&&!templates.length)return drawer('Start Team Review',permittedEmpty('A published review template is required before a team review can start.','Configure and publish a Review Template for this scope.',canManage()?'Configure Review Template':null,"seSwitchTab('configuration');seCloseDrawer()"));SE.activeReview=active&&active.id?active:{id:null,period:SE.period,status:'draft',owner_name:personName(),template_id:templates[0]&&templates[0].id,assessments:{},version_no:1};SE.reviewStep=1;seRenderTeamReview();};
window.seRenderTeamReview=function(){var r=SE.activeReview,steps=['Review setup','Data readiness','Employee assessments','Conclusions & actions','Review & submit'];var body='<div class="se-wizard-steps">'+steps.map(function(x,i){return '<button class="'+(SE.reviewStep===i+1?'active':'')+'" data-auris-module-onclick="f0059" data-auris-module-args="'+encodeURIComponent(JSON.stringify([(i+1)]))+'"><span>'+(i+1)+'</span>'+h(x)+'</button>';}).join('')+'</div><div class="se-wizard-body">'+reviewStepBody(r)+'</div><div class="se-autosave">Draft autosaves when moving between steps · Last saved '+h(r.updated_at?new Date(r.updated_at).toLocaleTimeString():'Not yet saved')+'</div>';var foot='<button class="se-btn" data-auris-module-onclick="f0020">Close</button>'+(SE.reviewStep>1?'<button class="se-btn" data-auris-module-onclick="f0059" data-auris-module-args="'+encodeURIComponent(JSON.stringify([(SE.reviewStep-1)]))+'">Back</button>':'')+'<button class="se-btn" data-auris-module-onclick="f0060">Save Draft</button>'+(SE.reviewStep<5?'<button class="se-btn primary" data-auris-module-onclick="f0059" data-auris-module-args="'+encodeURIComponent(JSON.stringify([(SE.reviewStep+1)]))+'">Continue</button>':'<button class="se-btn primary" data-auris-module-onclick="f0061">Submit Review</button>');drawer((r.id?'Resume':'Start')+' Team Review',body,foot);};
function collectReviewStep(){var r=SE.activeReview;if(SE.reviewStep===1){r.period=val('se-tr-period')||SE.period;r.team_name=val('se-tr-team');r.template_id=val('se-tr-template');r.owner_name=val('se-tr-owner');r.review_date=val('se-tr-date');r.meeting_date=val('se-tr-meeting')||null;r.participants=val('se-tr-participants').split(',').map(function(x){return x.trim();}).filter(Boolean);r.scope_note=val('se-tr-note');}else if(SE.reviewStep===3){r.assessments=r.assessments||{};inPeriod(SE.data.results).forEach(function(x){r.assessments[x.id]={decision:val('se-tr-assess-'+x.id),comment:val('se-tr-comment-'+x.id),result_snapshot:{score:x.score,status:x.status,pending:x.pending,formula_version:x.formula_version}};});}else if(SE.reviewStep===4){r.achievements=val('se-tr-achievements');r.barriers=val('se-tr-barriers');r.themes=val('se-tr-themes');r.actions_text=val('se-tr-actions');r.escalations=val('se-tr-escalations');r.conclusion=val('se-tr-conclusion');r.declaration=!!document.getElementById('se-tr-declaration')?.checked;}}
window.seReviewStep=async function(step){collectReviewStep();await seSaveTeamReview(false,true);if(!SE.activeReview.id)return;SE.reviewStep=step;seRenderTeamReview();};
window.seSaveTeamReview=async function(submit,silent){try{collectReviewStep();var r=SE.activeReview;if(submit){var total=inPeriod(SE.data.results).length;if(Object.keys(r.assessments||{}).length<total)throw new Error('Review every eligible employee before submission');if(!r.declaration)throw new Error('Supervisor declaration is required');}var payload={company_id:companyId(),period:r.period,team_name:r.team_name||'Direct reports',template_id:r.template_id,owner_id:personId(),owner_name:r.owner_name,review_date:r.review_date||new Date().toISOString().slice(0,10),meeting_date:r.meeting_date,participants:r.participants||[],scope_note:r.scope_note,readiness:{result_count:inPeriod(SE.data.results).length},assessments:r.assessments||{},conclusions:{achievements:r.achievements,barriers:r.barriers,themes:r.themes,actions_text:r.actions_text,escalations:r.escalations,conclusion:r.conclusion,declaration:r.declaration},snapshot:submit?{results:inPeriod(SE.data.results).map(function(x){return {id:x.id,score:x.score,status:x.status,formula_version:x.formula_version};}),created_at:new Date().toISOString()}:r.snapshot||{},status:submit?'submitted':'draft',version_no:r.version_no||1,updated_at:new Date().toISOString(),updated_by:personId()};var saved;if(r.id)saved=await patchRecord('teamReviews',r.id,payload,submit?'submitted':'autosaved');else{payload.id=uid('TR');payload.created_at=new Date().toISOString();payload.created_by=personId();saved=await persist('teamReviews',payload);SE.data.teamReviews.unshift(saved);}SE.activeReview=Object.assign(r,saved);if(submit){seCloseDrawer(true);render();toastMsg('Team review submitted with a versioned snapshot');}else if(!silent){seRenderTeamReview();toastMsg('Review Draft saved');}}catch(e){toastMsg('Review not saved: '+(e.message||'Please retry')+' — your entries remain open.',false);}};
